      "id": "b2-hetzen",
      "layout": "standardStudy",
      "translation": "подбуцнува • гони",
      "explanation": [
        "Главна идеја: hetzen е глагол со повеќе значења. Значи да пуштиш кучиња на некого, да гониш дивеч и да го бркаш; во пренесено значење — хушкање, поттикнување омраза (gegen jemanden hetzen). Без објект, со sein, може да значи и да брзаш, да трчаш: durch die Stadt hetzen.",
        "Форми: hetzt, hetzte, hat gehetzt (преоден) или ist gehetzt (во значење на движење). Чести изведенки: aufhetzen (подбуни, поттикне на омраза), die Hetze (хушкање; брзање).",
        "Во разговорниот јазик Hetz mich nicht! значи не ме брзај!"
      ],
      "examples": [
        {
          "de": "Der Jäger hetzt die Hunde auf den Hirsch.",
          "lv": "Ловецот ги пушта кучињата на еленот."
        },
        {
          "de": "Er hetzt gegen Ausländer.",
          "lv": "Тој хушка против странците."
        },
        {
          "de": "Die Hunde hetzten den Hasen über das Feld.",
          "lv": "Кучињата го гонеа зајакот низ полето."
        },
        {
          "de": "Ich bin den ganzen Tag durch die Stadt gehetzt.",
          "lv": "Цел ден брзав низ градот."
        },
        {
          "de": "Hetz mich nicht!",
          "lv": "Не ме брзај!"
        }
      ],
      "comparison": [
        {
          "word": "jagen",
          "meaning": "лови",
          "example": "Der Jäger jagt Rehe. – Ловецот лови срни."
        },
        {
          "word": "aufhetzen",
          "meaning": "подбунува",
          "example": "Er hetzt die Menge auf. – Тој ја подбунува толпата."
        },
        {
          "word": "eilen",
          "meaning": "брза",
          "example": "Ich eile zum Bahnhof. – Брзам кон станицата."
        }
      ],
      "tip": [
        "Во политички контекст hetzen gegen + акузатив значи да поттикнуваш омраза кон некого.",
        "Во ловечки контекст често: Hunde hetzen den Hasen."
      ],
      "important": [
        "Зборот hetzen често е негативен: хушкање или непријатно брзање.",
        "Во значењето на движење Perfekt се гради со sein (ist gehetzt), во другите случаи со haben."
      ],
