      "translation": "долготрајна тешка болест • страдање",
      "explanation": [
        "Главна идеја: das Leiden е именка од среден род што се користи на два начина: како страдање (das Leiden der Menschen) и како долготрајна, често хронична болест (ein schweres Leiden). Множината е die Leiden.",
        "Зборот е именка изведена од глаголот leiden (страда). Типични споеви: ein chronisches Leiden, ein altes Leiden, nach langem, schwerem Leiden (во некролози).",
        "Во споредба со обичното Krankheit, зборот Leiden ги нагласува траењето и тежината на болеста."
      ],
      "examples": [
        {
          "de": "Er hat ein schweres Leiden.",
          "lv": "Тој има тешка болест."
        },
        {
          "de": "Das Leiden der Patienten war groß.",
          "lv": "Страдањето на пациентите беше големо."
        },
        {
          "de": "Nach langem Leiden ist er gestorben.",
          "lv": "По долго страдање тој почина."
        },
        {
          "de": "Ein chronisches Leiden begleitet ihn seit Jahren.",
          "lv": "Хронична болест го придружува веќе години."
        }
      ],
      "comparison": [
        {
          "word": "die Krankheit",
          "meaning": "болест",
          "example": "Eine Krankheit kann ansteckend sein. – Болеста може да биде заразна."
        },
        {
          "word": "der Schmerz",
          "meaning": "болка",
          "example": "Der Schmerz ist stark. – Болката е силна."
        },
        {
          "word": "leiden",
          "meaning": "страда",
          "example": "Er leidet an Asthma. – Тој боледува од астма."
        }
      ],
      "tip": [
        "Со глаголот leiden кажи: an einer Krankheit leiden (боледува од некоја болест).",
        "Во некролози често ќе прочиташ: nach schwerem Leiden."
      ],
      "important": [
        "Leiden е именка со голема буква, а leiden — глагол со мала.",
        "Во секојдневието за краткотрајна болест се вели Krankheit, а не Leiden."
      ],
