      "layout": "standardStudy",
      "translation": "се помирува • се помири",
      "explanation": [
        "Главна идеја: sich versöhnen значи да се помириш по кавга или конфликт — да ги обновиш добрите односи со некого.",
        "Глаголот е повратен: ich versöhne mich, er versöhnt sich; во минато er versöhnte sich, во Perfekt er hat sich versöhnt. Со кого се помируваш, се означува со mit + датив: sich mit jemandem versöhnen.",
        "Зборот може да биде и преоден: jemanden versöhnen — да помириш некого (со друг)."
      ],
      "examples": [
        {
          "de": "Die Geschwister haben sich nach dem Streit versöhnt.",
          "lv": "Браќата и сестрите се помирија по кавгата."
        },
        {
          "de": "Ich möchte mich mit dir versöhnen.",
          "lv": "Сакам да се помирам со тебе."
        },
        {
          "de": "Er versöhnte sich mit seinem Vater.",
          "lv": "Тој се помири со својот татко."
        },
        {
          "de": "Wann versöhnt ihr euch endlich?",
          "lv": "Кога конечно ќе се помирите?"
        }
      ],
