        "Правилен глагол: er fordert, forderte, hat gefordert. Што се бара — акузатив, од кого — von + датив: etwas von jemandem fordern. Може да следува и реченица со dass. Во пренесено значење fordern може да значи да однесе жртви: Der Unfall forderte zwei Todesopfer.",
